<script setup lang="ts">
import { Plus, Pencil, Package, Link2, Play, Eye, AlertTriangle } from 'lucide-vue-next'
import { api, canWrite, money, platformName, platforms, time, type Row } from '../api'
import { useAction, useEditor, skuFields, competitorFields } from '../forms'
import FormModal from './FormModal.vue'
import StatusBadge from './StatusBadge.vue'
import EmptyState from './EmptyState.vue'
const props=defineProps<{ product:Row }>(), emit=defineEmits<{ changed:[] }>()
const editor=useEditor(()=>emit('changed')), action=useAction(()=>emit('changed'))
const base=()=>'/products/'+props.product.id
function editSku(sku:Row) { editor.open('编辑 SKU',[...skuFields.filter(f=>['sku_name','price','cost'].includes(f.key)),{key:'status',label:'状态',type:'select',options:[{value:'active',label:'启用'},{value:'inactive',label:'停用'}]},{key:'spec_json',label:'规格属性',type:'json'}],sku,base()+'/skus/'+sku.id,'PATCH') }
function inventory(sku:Row) { editor.open('调整库存 · '+sku.sku_name,[{key:'change_qty',label:'库存变动量',type:'number',step:1,required:true,hint:'补货填写正数，出库填写负数；修改阈值可填 0。'},{key:'locked_qty',label:'锁定数量',type:'number',step:1,min:0},{key:'warning_threshold',label:'预警阈值',type:'number',step:1,min:0},{key:'location_text',label:'库位'},{key:'reason_text',label:'调整原因',type:'textarea',required:true}],{change_qty:0,locked_qty:sku.locked_qty,warning_threshold:sku.warning_threshold,location_text:sku.location_text},base()+'/skus/'+sku.id+'/inventory-adjustments') }
function addMapping() { editor.open('添加平台商品映射',[{key:'platform',label:'目标平台',type:'select',options:platforms,required:true},{key:'platform_product_id',label:'平台商品编号',required:true},{key:'platform_sku_id',label:'平台 SKU 编号'}],{platform:'douyin'},base()+'/platform-mappings') }
function adopt(task:Row) { const result=task.result_json; editor.open('补充并录入竞品',competitorFields,{name:result.title,platform:props.product.platform,url:task.source_url,title:result.title,price:result.price,main_image:result.main_image,selling_points:result.selling_points},base()+'/competitors') }
</script>
<template>
  <div class="detail-columns"><section class="panel"><div class="panel-heading"><div><h2>商品档案</h2><p>真实、完整的信息，是好方案的起点</p></div></div><dl class="info-grid"><div><dt>商品名称</dt><dd>{{ product.name }}</dd></div><div><dt>商品类目</dt><dd>{{ product.category || '待补充' }}</dd></div><div><dt>售价 / 成本</dt><dd>{{ money(product.price) }} / {{ money(product.cost) }}</dd></div><div><dt>所属平台</dt><dd>{{ platformName(product.platform) }}</dd></div><div class="wide"><dt>目标人群</dt><dd>{{ product.target_audience || '待补充目标人群' }}</dd></div><div class="wide"><dt>核心卖点</dt><dd class="pre-wrap">{{ product.selling_points || '待补充可验证的商品卖点' }}</dd></div><div class="wide"><dt>商品链接</dt><dd><a v-if="product.product_url" :href="product.product_url" target="_blank" rel="noopener noreferrer" class="table-link">{{ product.product_url }}</a><span v-else>待补充</span></dd></div></dl></section>
  <section class="panel"><div class="panel-heading"><div><h2>多平台映射</h2><p>将不同平台的商品对应到同一档案</p></div><button v-if="canWrite()" class="icon-button" aria-label="添加平台映射" @click="addMapping"><Plus :size="18" /></button></div><div class="panel-body"><div v-for="mapping in product.platform_mappings" :key="mapping.id" class="mapping-row"><span class="platform-tag" :class="mapping.platform">{{ platformName(mapping.platform) }}</span><div><strong>{{ mapping.platform_product_id }}</strong><small>SKU：{{ mapping.platform_sku_id || '未关联' }}</small></div><span class="muted small">{{ mapping.mapping_status }}</span></div><p v-if="!product.platform_mappings.length" class="muted">暂无跨平台映射，需要时再补充即可。</p></div></section></div>
  <section class="panel section-block"><div class="panel-heading"><div><h2>SKU 与库存<span class="count-pill">{{ product.skus.length }}</span></h2><p>可用库存 = 现有库存 − 锁定库存</p></div><button v-if="canWrite()" class="button secondary small-button" @click="editor.open('新增 SKU',skuFields,{price:product.price,cost:product.cost,stock_qty:0,warning_threshold:10},base()+'/skus')"><Plus :size="15" />新增 SKU</button></div><div v-if="product.skus.length" class="table-wrap"><table><thead><tr><th>SKU / 规格</th><th>售价</th><th>现有 / 锁定</th><th>可用库存</th><th>预警阈值</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="sku in product.skus" :key="sku.id"><td><strong>{{ sku.sku_name }}</strong><small class="block muted">{{ sku.sku_code }} · {{ sku.location_text || '未设库位' }}</small></td><td>{{ money(sku.price) }}</td><td>{{ sku.stock_qty }} / {{ sku.locked_qty }}</td><td :class="{'text-warning':sku.low_stock}">{{ sku.available_qty }} <AlertTriangle v-if="sku.low_stock" :size="13" /></td><td>{{ sku.warning_threshold }}</td><td><StatusBadge :value="sku.status" :label="sku.status==='active'?'启用':'停用'" /></td><td><div v-if="canWrite()" class="inline-actions"><button class="text-button" @click="editSku(sku)">编辑</button><button class="text-button" @click="inventory(sku)">调整库存</button></div></td></tr></tbody></table></div><EmptyState v-else title="还没有 SKU" text="为商品建立规格，并登记初始库存。" /></section>
  <section class="panel section-block"><div class="panel-heading"><div><h2>竞品观察<span class="count-pill">{{ product.competitors.length }}</span></h2><p>记录公开信息，找到值得验证的差异</p></div><div class="inline-actions"><button v-if="canWrite()" class="button secondary small-button" @click="editor.open('解析公开商品链接',[{key:'source_url',label:'公开页面链接',required:true,hint:'仅解析公开静态元信息；需要登录的页面请改用人工录入。'}],{},base()+'/competitors/import-url-tasks')"><Link2 :size="14" />公开链接解析</button><button v-if="canWrite()" class="button secondary small-button" @click="editor.open('录入竞品',competitorFields,{platform:product.platform,price:0},base()+'/competitors')"><Plus :size="15" />录入竞品</button></div></div><div v-if="product.competitors.length" class="competitor-grid"><article v-for="c in product.competitors" :key="c.id" class="competitor-card"><div class="row-between"><span class="platform-tag" :class="c.platform">{{ platformName(c.platform) }}</span><button v-if="canWrite()" class="icon-button" aria-label="编辑竞品" @click="editor.open('编辑竞品',competitorFields,c,base()+'/competitors/'+c.id,'PATCH')"><Pencil :size="14" /></button></div><h3>{{ c.name }}</h3><strong class="competitor-price">{{ money(c.price) }}</strong><p>{{ c.selling_points || '待补充竞品卖点' }}</p><small>公开销量：{{ c.sales_hint || '未采集' }}</small><small>评价关键词：{{ c.review_keywords || '未录入' }}</small><div class="competitor-footer"><a v-if="c.url" :href="c.url" target="_blank" rel="noopener noreferrer" class="table-link">公开页面 <Link2 :size="12" /></a><button v-if="canWrite()" class="text-button" :disabled="!!action.busy" @click="action.run('monitor-'+c.id,()=>api(base()+'/competitors/'+c.id+'/monitor','POST',{interval_minutes:1440,monitor_status:c.monitors[0]?.monitor_status==='active'?'paused':'active'}),'监控设置已更新')"><Eye :size="13" />{{ c.monitors[0]?.monitor_status==='active'?'暂停监控':'启用监控' }}</button></div><div v-if="c.monitors[0]" class="monitor-note"><span>每 {{ c.monitors[0].interval_minutes }} 分钟 · 下次 {{ time(c.monitors[0].next_run_at) }}</span><p v-if="c.monitors[0].snapshots.length">最近结果：{{ c.monitors[0].snapshots[0].raw_payload_json.parse_status==='failed' ? c.monitors[0].snapshots[0].raw_payload_json.error_message : '公开元信息已记录' }}</p></div></article></div><EmptyState v-else title="了解同一市场里的其他选择" text="先录入两到三个同规格竞品，让商品诊断更有依据。" />
  <div v-if="product.parse_tasks.length" class="panel-body border-top"><h3>公开链接解析任务</h3><div v-for="task in product.parse_tasks" :key="task.id" class="parse-task"><div class="row-between"><span class="truncate small">{{ task.source_url }}</span><StatusBadge :value="task.task_status" /></div><p v-if="task.error_message" class="text-warning small">{{ task.error_message }}</p><p v-if="task.result_json.title" class="small">{{ task.result_json.title }}</p><div v-if="canWrite()" class="inline-actions"><button v-if="task.task_status!=='succeeded'" class="text-button" :disabled="!!action.busy" @click="action.run('parse-'+task.id,()=>api(base()+'/link-parse-tasks/'+task.id+'/run','POST'),'解析任务已执行，请查看结果')"><Play :size="13" />{{ task.attempts?'重新解析':'运行解析' }}</button><button v-else class="text-button" @click="adopt(task)">补充并录入竞品 <Plus :size="13" /></button></div></div></div></section>
  <section v-if="product.inventory_movements.length" class="panel section-block"><div class="panel-heading"><div><h2>最近库存流水</h2></div></div><div class="table-wrap"><table><thead><tr><th>时间</th><th>SKU</th><th>变化</th><th>调整前 → 调整后</th><th>原因</th></tr></thead><tbody><tr v-for="m in product.inventory_movements.slice(0,8)" :key="m.id"><td>{{ time(m.created_at) }}</td><td>{{ product.skus.find((s:Row)=>s.id===m.sku_id)?.sku_name }}</td><td>{{ m.change_qty>0?'+':'' }}{{ m.change_qty }}</td><td>{{ m.before_qty }} → {{ m.after_qty }}</td><td>{{ m.reason_text }}</td></tr></tbody></table></div></section>
  <FormModal v-if="editor.form" v-bind="editor.form" :saving="editor.saving" :error="editor.error" @close="editor.close" @submit="editor.save" />
</template>
